INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63023588', 63023588, 'analyze_legacy', 'Kota Surakarta', 'kabkota', 'PUSKESMAS JAYENGAN', 'PMT hamil ibu KEK & resiko KEK', 'Barang', 'E-Purchasing', 'Jawa Tengah, Surakarta (Kota)', 8856000, 'January 2026', 'APBD', 1, 1, '3 Orang x 120 Hari', 'PMT hamil ibu KEK & resiko KEK;', 'Pekerjaan Pemberian Makanan Tambahan (PMT) bagi ibu hamil dengan Kekurangan Energi Kronis (KEK) dan/atau anemia merupakan kegiatan penyediaan makanan tambahan bergizi guna meningkatkan status gizi ibu hamil dan mendukung kesehatan ibu serta janin. PMT diberikan kepada ibu hamil sasaran yang terdaftar di Puskesmas sesuai hasil pemeriksaan status gizi dan hemoglobin. Makanan tambahan harus memenuhi standar gizi ibu hamil, mengandung energi dan protein tinggi, serta diperkaya vitamin dan mineral terutama zat besi, asam folat, dan vitamin C. PMT disediakan dalam bentuk makanan siap konsumsi atau bahan pangan olahan yang aman, higienis, dan layak konsumsi. Pelaksanaan PMT dilakukan secara teratur selama periode 120 hari, disertai pencatatan, pelaporan, serta pemantauan kepatuhan dan status gizi ibu hamil sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 473670);
