INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62413598', 62413598, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Makan Rapat Biasa D.I. YOGYAKARTA produksi feature', 'Barang', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 3000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 60, OK, @ 50000 )', '1. Makan Rapat Biasa D.I. YOGYAKARTA ( 60, OK, @ 50000 ); Program produksi feature', 'Pengadaan konsumsi makan rapat biasa diperuntukkan bagi kegiatan Produksi Feature yang dilaksanakan dalam 1 (satu) kegiatan, dengan jumlah peserta sebanyak 60 orang. Konsumsi disediakan untuk mendukung kelancaran koordinasi dan pelaksanaan rapat produksi. Konsumsi disajikan dalam bentuk makan rapat biasa (nasi box) yang terdiri dari nasi putih, lauk utama, lauk pendamping, sayur, sambal, dan air mineral, diproduksi oleh penyedia jasa boga/katering yang memenuhi standar kebersihan dan keamanan pangan. Penyedia wajib melakukan pengantaran tepat waktu sesuai jadwal rapat, dengan makanan diproduksi pada hari pelaksanaan dan dikemas secara rapi menggunakan kemasan food grade.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 474950);
